local function lz4decode(data)
    local chunks,chars={},{}
    local ring,ringPos={},0
    local function emit(b)
        ringPos=ringPos+1; ring[(ringPos-1)%65536]=b
        chars[#chars+1]=string.char(b)
        if #chars>=4096 then chunks[#chunks+1]=table.concat(chars); chars={} end
    end
    local function emitRange(i,len)
        for j=i,i+len-1 do emit(data:byte(j)) end
        return i+len
    end
    local i,n=1,#data
    while i<=n do
        local t=data:byte(i); i=i+1
        local ll=math.floor(t/16)
        if ll==15 then repeat local x=data:byte(i); i=i+1; ll=ll+x until x~=255 end
        if ll>0 then i=emitRange(i,ll) end
        if i>n then break end
        local lo,hi=data:byte(i),data:byte(i+1); i=i+2
        local off=lo+hi*256
        local ml=t%16
        if ml==15 then repeat local x=data:byte(i); i=i+1; ml=ml+x until x~=255 end
        ml=ml+4
        for _=1,ml do emit(ring[(ringPos-off)%65536]) end
    end
    if #chars>0 then chunks[#chunks+1]=table.concat(chars) end
    return table.concat(chunks)
end
